### Props Props ## withSkeleton withSkeleton HOC  `withSkeleton`  позволяет применить анимацию скелетона к любому компоненту.
При  `skeleton={true}`  заменяется фоновый цвет компонента, добавляется градиент, а текст становится прозрачным. ### Быстрый старт Быстрый старт ```tsx
import React from 'react';
import { Button, withSkeleton } from '@salutejs/sdds-finai';

export function App() {
    const ButtonSkeleton = withSkeleton(Button);

    return (
        <ButtonSkeleton
            fullWidth
            text="Загрузка..."
            view="primary"
            size="s"
            scaleOnInteraction={false}
            outlined={false}
            skeleton={true}
            tabIndex={-1}
        />
    );
}
```

### Тип анимации Тип анимации Тип анимации задаётся через проп  `animationConfig`  с обязательным полем  `type` . ```tsx
import React from 'react';
import { Button, withSkeleton } from '@salutejs/sdds-finai';

export function App() {
    const ButtonSkeleton = withSkeleton(Button);

    return (
        <ButtonSkeleton
            text="Загрузка..."
            view="default"
            size="s"
            skeleton={true}
            animationConfig={{ type: 'shimmer' }}
        />
    );
}
```

```tsx
import React from 'react';
import { Button, withSkeleton } from '@salutejs/sdds-finai';

export function App() {
    const ButtonSkeleton = withSkeleton(Button);

    return (
        <ButtonSkeleton
            text="Загрузка..."
            view="default"
            size="s"
            skeleton={true}
            animationConfig={{ type: 'pulse' }}
        />
    );
